Lemma mb_seg1 : forall (ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word)
    (F : bvmap 5 word) (fc : bv 32) (m : mem) (bb first lo : Z) (wprev : word),
  a0 = wz bb ->
  rw_cells rsegs m (bb + 8) [C8 (wz first); C8 wprev] -> 0 <= first < 2^64 ->
  stk rsegs m lo (bv_unsigned sp) -> lo + 32 <= bv_unsigned sp -> hceil <= lo ->
  bv_unsigned sp <= bb -> bb + 24 <= 2^64 ->
  mem_inv rsegs m ->
  evt rsegs (mb_seg1_post ra sp gp tp s1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc t0 t1 t2 t3 t4 t5 t6 s0 bb first lo m)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (wz P_MBUF_DTOR) fc None m (seg_rom rsegs)).
