(* [comment removed for export] *)
Definition powned (em : gmap Z elt) (h : hdrv) (es : list mbe) (b : block) : Prop := bfowned em h b \/ mbowned es b.

(* [comment removed for export] *)
Definition BodyDisj (em : gmap Z elt) (h : hdrv) (es : list mbe) : Prop :=
  forall x s, In (x, s) es -> em !! x = None /\ (1 <= hv_ml h -> x <> hv_mp h) /\ (1 <= hv_tl h -> x <> hv_tp h).

(* [comment removed for export] *)
Definition ParserCoreCellsD (c : pcore) (pad7 pad2 : list byte) : list cell :=
  C8 (wz VP_BASIC_PARSER) :: tl (ParserCoreCells c pad7 pad2).

(* [comment removed for export] *)
Definition parser_dtor_X (P : Z) : list (Z * Z) := [(P, P + 8); (P + 40, P + 48); (P + 128, P + 160)]%Z.

(* [comment removed for export] *)
Lemma FieldsC_xpres : forall LB SP X m m' Fa S L ns ls em,
  FieldsC m Fa S L ns ls em -> FieldsOwn LB em -> xpres LB SP X m m' -> SP <= Fa ->
  Forall (fun iv : Z * Z => Fa + 48 <= fst iv \/ snd iv <= Fa) X ->
  (forall e d, em !! e = Some d -> Forall (fun iv : Z * Z => e + esize d <= fst iv \/ snd iv <= e) X) ->
  FieldsC m' Fa S L ns ls em.
Proof.
  intros LB SP X m m' Fa S L ns ls em FC OWN XP LE XB XE.
  pose proof FC as (NC & LC & EC & OK & SO & DL & SL & LE' & EOK & HH & HB & AL).
  assert (XSUB : forall a n a' n', Forall (fun iv : Z * Z => a + n <= fst iv \/ snd iv <= a) X -> a <= a' -> a' + n' <= a + n ->
                 Forall (fun iv : Z * Z => a' + n' <= fst iv \/ snd iv <= a') X).
  { intros a n a' n' F L1 L2. eapply Forall_impl; [| exact F]. intros [u v]; cbn; lia. }
  assert (ESUB : forall e d a' n', em !! e = Some d -> e <= a' -> a' + n' <= e + esize d -> xclient_range LB SP X a' n').
  { intros e d a' n' Ld L1 L2. destruct (OWN e d Ld) as [p [INp _]]. split.
    - right; right. exists (p, e, esize d). split; [exact INp| cbn; lia].
    - eapply XSUB; [exact (XE e d Ld)| lia| lia]. }
  split.
  { intros a nd La. destruct (NC a nd La) as [WF [pad C]]. split; [exact WF|]. exists pad.
    eapply xpres_rw_cells; [exact XP| exact C|]. rewrite NodeCells_size.
    destruct (FieldsC_node_cases _ _ _ _ _ _ _ _ _ FC La) as [->|(d & Ld & _ & P0 & _ & R)].
    - split; [left; lia| eapply XSUB; [exact XB| lia| cbn; lia]].
    - pose proof (esize_ge d). eapply ESUB; [exact Ld| lia| cbn; lia]. }
  split.
  { intros a n La. destruct (LC a n La) as [WF C]. split; [exact WF|].
    eapply xpres_rw_cells; [exact XP| exact C|]. rewrite LNodeCells_size.
    destruct (FieldsC_lnode_cases _ _ _ _ _ _ _ _ _ FC La) as [->|(d & Ld & _ & P0 & _ & R)].
    - split; [left; lia| eapply XSUB; [exact XB| lia| cbn; lia]].
    - pose proof (esize_ge d). eapply ESUB; [exact Ld| lia| cbn; lia]. }
  split.
  { intros e d Ld. eapply xpres_rw_cells; [exact XP| exact (EC e d Ld)|]. rewrite ValCells_size.
    eapply ESUB; [exact Ld| lia| lia]. }
  split; [exact OK|]. split; [exact SO|]. split; [exact DL|]. split; [exact SL|]. split; [exact LE'|].
  split; [exact EOK|]. split; [exact HH|]. split; [exact HB| exact AL].
Qed.

(* [comment removed for export] *)
Definition pd_seg1_post (sp gp tp a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (t0 t1 t2 t3 t4 t5 t6 ra s0 s1 : word) (P lo : Z) (c : pcore) (pad7 pad2 : list byte) (m : mem) : machine_state -> Prop :=
  fun ms' => exists m' junk,
    ms' = MS (mkR (wz PD_RA1) (wz (bv_unsigned sp + -32)) gp tp t0 t1 t2 (wz P) (wz (P + 80)) (wz (P + 168)) (wz (P + 256)) (wz (P + 304))
                  a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (wz P_MBUF_DTOR) fc None m' (seg_rom rsegs)
    /\ munch [(bv_unsigned sp + -32, bv_unsigned sp); (P, P + 8)]%Z m m' /\ wmono rsegs m m' /\ mem_inv rsegs m'
    /\ stk rsegs m' lo (bv_unsigned sp + -32)
    /\ rw_cells rsegs m' (bv_unsigned sp + -32) [CB 8 junk; C8 s1; C8 s0; C8 ra]
    /\ rw_cells rsegs m' P (ParserCoreCells c pad7 pad2)
    /\ rw_cells rsegs m' (P + 288) [C8 (wz 0)] /\ rw_cells rsegs m' (P + 336) [C8 (wz 0)].

Lemma pd_seg1 : forall (ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word)
    (F : bvmap 5 word) (fc : bv 32) (m : mem) (P lo : Z) (c : pcore) (pad7 pad2 : list byte),
  a0 = wz P ->
  rw_cells rsegs m P (ParserCoreCells c pad7 pad2) ->
  rw_cells rsegs m (P + 288) [C8 (wz 0)] -> rw_cells rsegs m (P + 336) [C8 (wz 0)] ->
  stk rsegs m lo (bv_unsigned sp) -> lo + 32 <= bv_unsigned sp -> hceil <= lo ->
  bv_unsigned sp <= P -> P + 344 <= 2^64 ->
  mem_inv rsegs m ->
  evt rsegs (pd_seg1_post sp gp tp a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc t0 t1 t2 t3 t4 t5 t6 ra s0 s1 P lo c pad7 pad2 m)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
