Section W.
  Variable H : hsr.
  Hypothesis HH : heap_sr_hyps H.

  Definition parser_dtor_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
      (s : PState) (LB : list block) (P lo B : Z) (c : pcore) (pad7 pad2 : list byte) (em : gmap Z elt) (h : hdrv) (es : list mbe)
      (errv : word) (m : mem) (mo : Model) : config -> Prop :=
    fun cf => exists t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m' (s' : PState) (LB' : list block),
      cfg_ms cf = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
                    F (ret_pc ra) fc None m' (seg_rom rsegs)
      /\ hs_KREL H s' (cfg_model cf) /\ hs_MPRES H mo (cfg_model cf)
      /\ mem_inv rsegs m' /\ stk rsegs m' lo (bv_unsigned sp)
      /\ rw_cells rsegs m' (errno_addr tp) [C4 errv] /\ hs_rauxv_ok H m' B
      /\ hs_RHEAP H s' LB' m'
      /\ (forall b, In b LB' <-> (In b LB /\ ~ powned em h es b))
      /\ lb_bytes LB' <= lb_bytes LB /\ (length LB' <= length LB)%nat
      /\ rw_cells rsegs m' P (ParserCoreCellsD c pad7 pad2)
      /\ rw_cells rsegs m' (P + 128) (HdrCells (hdr_cleared h))
      /\ rw_cells rsegs m' (P + 288) [C8 (wz 0)] /\ rw_cells rsegs m' (P + 336) [C8 (wz 0)]
      /\ xpres LB' (bv_unsigned sp) (parser_dtor_X P) m m'.

  Definition parser_dtor_stmt : Prop :=
    forall (ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word)
           (F : bvmap 5 word) (fc : bv 32) (m : mem) (mo : Model)
           (s : PState) (LB : list block) (P lo B : Z) (c : pcore) (pad7 pad2 : list byte)
           (S L : list Z) (ns : NS) (ls : LS) (em : gmap Z elt) (h : hdrv)
           (es : list mbe) (out insz outpos outend : Z) (errv : word),
      a0 = wz P ->
      rw_cells rsegs m P (ParserCoreCells c pad7 pad2) ->
      rw_cells rsegs m (P + 288) [C8 (wz 0)] -> rw_cells rsegs m (P + 336) [C8 (wz 0)] ->
      FieldsC m (P + 80) S L ns ls em -> FieldsOwn LB em ->
      rw_cells rsegs m (P + 128) (HdrCells h) -> HdrOwn LB h -> HdrDisj em h ->
      MBraw m (P + 168) es out insz outpos outend -> MBufOwn LB es -> BodyDisj em h es ->
      bv_unsigned sp <= P -> P + 160 <= B ->
      hs_RHEAP H s LB m -> hs_KREL H s mo ->
      hs_rauxv_ok H m B -> bv_unsigned sp <= B ->
      stk rsegs m lo (bv_unsigned sp) -> hceil <= lo -> lo <= bv_unsigned sp - PARSER_DTOR_STACK ->
      rw_cells rsegs m (errno_addr tp) [C4 errv] -> mem_inv rsegs m -> tp = wz RATP ->
      hs_SR H (parser_dtor_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc s LB P lo B c pad7 pad2 em h es errv m mo)
        (mkCfg (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
                   F (wz P_PARSER_DTOR) fc None m (seg_rom rsegs)) mo).

  Lemma parser_dtor_spec : parser_dtor_stmt.
  Proof.
    intros until errv. intros -> PC F1 F2 FC FOWN HDR HOWN HDJ MB MOWN BDJ SP0 PB HP KREL AUX SPB ST CEIL LO ERR MI TP.
    unfold PARSER_DTOR_STACK, BFIELDS_DTOR_STACK, RFREE_STACK in LO. pose proof CEIL as CEIL'. hcb. unfold wz in *. subst tp.
    assert (EA : errno_addr (Z_to_bv 64 RATP) = RERRNO) by (unfold RATP, RERRNO; rewrite unsigned_lit; lia).
    rewrite EA in ERR. sp_range sp.
    pose proof (blocks_below_hceil H HH _ _ _ HP) as HBK.
    pose proof FC as (_ & _ & _ & _ & _ & _ & _ & LE & EOK & HFa & _).
    pose proof MB as (lsb & MB0 & MB1 & DLb & LCb & ELb & AOK). pose proof AOK as (AD & _ & HBB & B64 & BAL).
    pose proof (rw_cells_bound _ _ _ _ HDR) as HB. unfold HdrCells in HB. cbn [cells_size csize Nat.add length] in HB.
    pose proof (rw_cells_bound _ _ _ _ F2) as HB2. cbn [cells_size csize Nat.add length] in HB2.
    (* [comment removed for export] *)
    eapply (hh_evt_then H HH); [exact KREL| eapply pd_seg1; try eassumption; try reflexivity; lia|].
    intros ms1 PO. unfold pd_seg1_post in PO. destruct PO as (m1 & junk & -> & MU & WM & MI1 & ST1 & FR1 & PC1 & F11 & F21). unfold wz.
    eapply (rw_cells_transport rsegs _ m m1) in ERR; [| exact MU| exact WM| unfold RERRNO in *; cbn; lia].
    eapply (rw_cells_transport rsegs _ m m1) in HDR; [| exact MU| exact WM| cbn; lia].
    assert (HP1 : hs_RHEAP H s LB m1).
    { eapply (hh_RHEAP_frame H HH); [exact HP| exact MU| exact WM|]. constructor; [left; cbn; lia|]. constructor; [left; cbn; lia| constructor]. }
    assert (AUX1 : hs_rauxv_ok H m1 B).
    { eapply (hh_rauxv_frame H HH); [exact AUX| exact MU| exact WM|]. unfold RAUXV_CELL in *.
      constructor; [cbn; lia|]. constructor; [cbn; lia| constructor]. }
    assert (XPm1 : xpres LB (bv_unsigned sp) [(P, P + 8)]%Z m m1).
    { eapply xpres_of_munch; [exact MU| exact WM| | exact HBK].
      constructor; [left; cbn; lia|]. constructor; [right; cbn; intros a Ha; left; lia| constructor]. }
    assert (FC1 : FieldsC m1 (P + 80) S L ns ls em).
    { eapply FieldsC_xpres; [exact FC| exact FOWN| exact XPm1| lia| |].
      - constructor; [cbn; lia| constructor].
      - intros e d Ld. pose proof (em_ok_range _ _ _ EOK Ld) as (_ & _ & R & _). constructor; [cbn; lia| constructor]. }
    assert (MBR1 : MBraw m1 (P + 168) es out insz outpos outend).
    { eapply MBraw_xpres; [exact MB| exact MOWN| exact XPm1| lia| |].
      - constructor; [cbn; lia| constructor].
      - intros x sz IN. pose proof (AD x sz IN) as (_ & _ & _ & R). constructor; [cbn; lia| constructor]. }
    (* [comment removed for export] *)
    pose proof (mbuf_dtor_spec H HH) as MS_. unfold mbuf_dtor_stmt in MS_.
    eapply (hh_seq H HH).
    { eapply MS_ with (sp := Z_to_bv 64 (bv_unsigned sp + -32)) (lo := lo) (B := B); unfold wz; rewrite ?unsigned_lit by lia;
        try reflexivity; try eassumption; try lia.
      all: try solve [ unfold MBUF_DTOR_STACK, RFREE_STACK; lia | rewrite EA; exact ERR ]. }
    clear MS_. intros [ms2 mo2] PO. unfold mbuf_dtor_post in PO. cbn [cfg_ms cfg_model] in PO.
    destruct PO as (u0 & u1 & u2 & c0 & c1 & c2 & c3 & c4 & c5 & c6 & c7 & u3 & u4 & u5 & u6 & m2 & s2' & LB2 &
                    -> & KREL2 & MP2 & MI2 & ST2 & ERR2 & AUX2 & HEAP2 & MEM2 & BY2 & LEN2 & XP2).
    unfold wz in *. rewrite (unsigned_lit (bv_unsigned sp + -32)) in ST2, XP2 by lia. rewrite EA in ERR2.
    assert (FR2 : rw_cells rsegs m2 (bv_unsigned sp + -32) [CB 8 junk; C8 s1; C8 s0; C8 ra]).
    { eapply xpres_rw_cells; [exact XP2| exact FR1|]. split; [left; lia| constructor]. }
    assert (PC2 : rw_cells rsegs m2 P (ParserCoreCells c pad7 pad2)).
    { eapply xpres_rw_cells; [exact XP2| exact PC1|]. split; [left; lia| constructor]. }
    assert (F12 : rw_cells rsegs m2 (P + 288) [C8 (Z_to_bv 64 0)]).
    { eapply xpres_rw_cells; [exact XP2| exact F11|]. split; [left; lia| constructor]. }
    assert (F22 : rw_cells rsegs m2 (P + 336) [C8 (Z_to_bv 64 0)]).
    { eapply xpres_rw_cells; [exact XP2| exact F21|]. split; [left; lia| constructor]. }
    assert (HDR2 : rw_cells rsegs m2 (P + 128) (HdrCells h)).
    { eapply xpres_rw_cells; [exact XP2| exact HDR|]. split; [left; lia| constructor]. }
    assert (FOWN2 : FieldsOwn LB2 em).
    { intros e d Ld. destruct (FOWN e d Ld) as [p [INp SZ]]. exists p. split; [| exact SZ]. apply MEM2. split; [exact INp|].
      intros (sz & INe & _). cbn in INe. destruct (BDJ _ _ INe) as [K _]. rewrite K in Ld. discriminate. }
    assert (HOWN2 : HdrOwn LB2 h).
    { destruct HOWN as (OM & OT & RM & RT). split; [| split; [| split; [exact RM| exact RT]]].
      - destruct OM as [K|[K1 [pm INm]]]; [left; exact K| right]. split; [exact K1|]. exists pm. apply MEM2. split; [exact INm|].
        intros (sz & INe & _). cbn in INe. destruct (BDJ _ _ INe) as (_ & K & _). exact (K K1 eq_refl).
      - destruct OT as [K|[K1 [pt INt]]]; [left; exact K| right]. split; [exact K1|]. exists pt. apply MEM2. split; [exact INt|].
        intros (sz & INe & _). cbn in INe. destruct (BDJ _ _ INe) as (_ & _ & K). exact (K K1 eq_refl). }
    assert (FC2 : FieldsC m2 (P + 80) S L ns ls em).
    { eapply FieldsC_xpres; [exact FC1| exact FOWN2| exact XP2| lia| constructor| intros; constructor]. }
    (* [comment removed for export] *)
    eapply (hh_evt_then H HH); [exact KREL2| eapply pd_seg2; [right; reflexivity| exact MI2]|].
    intros ms3 ->. unfold wz.
    (* [comment removed for export] *)
    pose proof (bfields_dtor_spec H HH) as BF. unfold bfields_dtor_stmt in BF.
    eapply (hh_seq H HH).
    { eapply BF with (sp := Z_to_bv 64 (bv_unsigned sp + -32)) (lo := lo) (B := B) (Fa := P + 80); unfold wz; rewrite ?unsigned_lit by lia;
        try reflexivity; try eassumption; try lia.
      all: try solve [ unfold BFIELDS_DTOR_STACK, RFREE_STACK; lia | rewrite EA; exact ERR2
                     | replace (P + 80 + 48) with (P + 128) by lia; exact HDR2 ]. }
    clear BF. intros [ms4 mo4] PO. unfold bfields_dtor_post in PO. cbn [cfg_ms cfg_model] in PO.
    destruct PO as (v0 & v1 & v2 & d0 & d1 & d2 & d3 & d4 & d5 & d6 & d7 & v3 & v4 & v5 & v6 & m4 & s4' & LB4 &
                    -> & KREL4 & MP4 & MI4 & ST4 & ERR4 & AUX4 & HEAP4 & MEM4 & BY4 & LEN4 & HDR4 & XP4).
    unfold wz in *. rewrite (unsigned_lit (bv_unsigned sp + -32)) in ST4, XP4 by lia. rewrite EA in ERR4.
    replace (P + 80 + 48) with (P + 128) in HDR4, XP4 by lia. replace (P + 80 + 80) with (P + 160) in XP4 by lia.
    assert (FR4 : rw_cells rsegs m4 (bv_unsigned sp + -32) [CB 8 junk; C8 s1; C8 s0; C8 ra]).
    { eapply xpres_rw_cells; [exact XP4| exact FR2|]. split; [left; lia| constructor; [cbn; lia| constructor]]. }
    assert (PC4 : rw_cells rsegs m4 P (ParserCoreCells c pad7 pad2)).
    { eapply xpres_rw_cells; [exact XP4| exact PC2|]. split; [left; lia|]. unfold ParserCoreCells. constructor; [cbn; lia| constructor]. }
    assert (F14 : rw_cells rsegs m4 (P + 288) [C8 (Z_to_bv 64 0)]).
    { eapply xpres_rw_cells; [exact XP4| exact F12|]. split; [left; lia| constructor; [cbn; lia| constructor]]. }
    assert (F24 : rw_cells rsegs m4 (P + 336) [C8 (Z_to_bv 64 0)]).
    { eapply xpres_rw_cells; [exact XP4| exact F22|]. split; [left; lia| constructor; [cbn; lia| constructor]]. }
    (* [comment removed for export] *)
    eapply (hh_evt H HH); [exact KREL4| eapply pd_seg3; try eassumption; try lia; right; reflexivity|].
    intros ms5 (a1v & m5 & -> & MU5 & WM5 & MI5 & ST5 & PC5). unfold parser_dtor_post. cbn [cfg_ms cfg_model].
    pose proof (blocks_below_hceil H HH _ _ _ HEAP4) as HBK4.
    do 15 eexists. exists m5, s4', LB4. split; [reflexivity|]. split; [exact KREL4|].
    split; [eapply (hh_mpres_trans H HH); [exact MP2| exact MP4]|].
    split; [exact MI5|]. split; [exact ST5|].
    split. { rewrite EA. eapply (rw_cells_transport rsegs _ m4 m5); [exact ERR4| exact MU5| exact WM5| unfold RERRNO in *; cbn; lia]. }
    split. { eapply (hh_rauxv_frame H HH); [exact AUX4| exact MU5| exact WM5|]. unfold RAUXV_CELL in *.
             constructor; [cbn; lia|]. constructor; [cbn; lia| constructor]. }
    split. { eapply (hh_RHEAP_frame H HH); [exact HEAP4| exact MU5| exact WM5|].
             constructor; [left; cbn; lia|]. constructor; [left; cbn; lia| constructor]. }
    split. { intros b. rewrite MEM4, MEM2. unfold powned. tauto. }
    split; [lia|]. split; [lia|]. split; [exact PC5|].
    split. { eapply (rw_cells_transport rsegs _ m4 m5); [exact HDR4| exact MU5| exact WM5|]. unfold HdrCells. cbn. lia. }
    split. { eapply (rw_cells_transport rsegs _ m4 m5); [exact F14| exact MU5| exact WM5|]. cbn. lia. }
    split. { eapply (rw_cells_transport rsegs _ m4 m5); [exact F24| exact MU5| exact WM5|]. cbn. lia. }
    (* [comment removed for export] *)
    assert (S42 : forall b, In b LB4 -> In b LB2). { intros b Hb. apply MEM4. exact Hb. }
    unfold parser_dtor_X.
    eapply xpres_trans; [| eapply xpres_trans; [| eapply xpres_trans]].
    + eapply xpres_of_munch; [exact MU| exact WM| | exact HBK4].
      constructor; [left; cbn; lia|]. constructor; [right; cbn; intros a Ha; left; lia| constructor].
    + eapply xpres_weaken; [exact XP2| lia| exact S42| intros a K; destruct K].
    + eapply xpres_weaken; [exact XP4| lia| intros b Hb; exact Hb| intros a K; cbn in K |- *; lia].
    + eapply xpres_of_munch; [exact MU5| exact WM5| | exact HBK4].
      constructor; [right; cbn; intros a Ha; left; lia|]. constructor; [right; cbn; intros a Ha; right; left; lia| constructor].
  Qed.

  (* [comment removed for export] *)
  Lemma powned_in_owner : forall s LB m LBo bb es em h b,
    hs_RHEAP H s LB m -> (forall b', In b' LBo -> In b' LB) ->
    FieldsOwn LBo em -> HdrOwn LBo h -> MBufOwn LBo es -> mb_addr_ok bb es ->
    In b LB -> powned em h es b -> In b LBo.
  Proof.
    intros s LB m LBo bb es em h b HP SUB FO HO MO AOK Hb PO.
    destruct PO as [[Fo|[Sv|Sv]]|Mo].
    - destruct Fo as (d & Ld & SZ). destruct (FO _ _ Ld) as [p [INp _]]. pose proof (esize_ge d).
      assert (E : b = (p, blk_addr b, esize d)) by (eapply (blk_same H HH); [exact HP| exact Hb| apply SUB; exact INp| reflexivity| cbn; lia| lia]).
      rewrite E. exact INp.
    - destruct Sv as (L1 & EA & ES). destruct HO as (OM & _). destruct OM as [[K _]|[_ [p INp]]]; [lia|].
      assert (b = (p, hv_mp h, hv_ml h)) by (eapply (blk_same H HH); [exact HP| exact Hb| apply SUB; exact INp| exact EA| exact ES| lia]).
      subst b. exact INp.
    - destruct Sv as (L1 & EA & ES). destruct HO as (_ & OT & _). destruct OT as [[K _]|[_ [p INp]]]; [lia|].
      assert (b = (p, hv_tp h, hv_tl h)) by (eapply (blk_same H HH); [exact HP| exact Hb| apply SUB; exact INp| exact EA| exact ES| lia]).
      subst b. exact INp.
    - destruct Mo as (sz & INe & SZ). destruct (MO _ _ INe) as [p INp]. destruct AOK as (AD & _).
      destruct (AD _ _ INe) as (_ & _ & S0 & _). pose proof (mb_block_size_range sz S0) as [RS _].
      assert (E : b = (p, blk_addr b, mb_block_size sz)) by (eapply (blk_same H HH); [exact HP| exact Hb| apply SUB; exact INp| reflexivity| cbn; lia| lia]).
      rewrite E. exact INp.
  Qed.

  (* [comment removed for export] *)
  Lemma FieldsOwn_mono : forall LBo LB em, (forall b, In b LBo -> In b LB) -> FieldsOwn LBo em -> FieldsOwn LB em.
  Proof. intros LBo LB em SUB FO e d Ld. destruct (FO e d Ld) as [p [INp SZ]]. exists p. split; [apply SUB; exact INp| exact SZ]. Qed.
  Lemma HdrOwn_mono : forall LBo LB h, (forall b, In b LBo -> In b LB) -> HdrOwn LBo h -> HdrOwn LB h.
  Proof.
    intros LBo LB h SUB (OM & OT & RM & RT). split; [| split; [| split; [exact RM| exact RT]]].
    - destruct OM as [K|[K1 [p INp]]]; [left; exact K| right]. split; [exact K1|]. exists p. apply SUB. exact INp.
    - destruct OT as [K|[K1 [p INp]]]; [left; exact K| right]. split; [exact K1|]. exists p. apply SUB. exact INp.
  Qed.
  Lemma MBufOwn_mono : forall LBo LB es, (forall b, In b LBo -> In b LB) -> MBufOwn LBo es -> MBufOwn LB es.
  Proof. intros LBo LB es SUB MO x sz IN. destruct (MO x sz IN) as [p INp]. exists p. apply SUB. exact INp. Qed.

  (* [comment removed for export] *)
  Lemma MBuf_MBraw : forall m b es insz, MBuf m b es insz -> MBraw m b es (mb_out b es insz) insz (mb_outpos es insz) (mb_outpos es insz).
  Proof. intros m b es insz [R _]. exact R. Qed.
